const ASTRO_DATABASE = {};

function buildComputedDay(dateKey, r) {
    const wMeta = WEEKDAY_META[r.dow];
    const p = r.p;
    const nakName = r.nakShort;
    const baseScore = r.caution ? 52 : ([0, 3, 4, 6, 7, 11, 12, 13, 14, 16, 20, 21, 22, 25, 26].includes(r.nakshatraIndex) ? 88 : 74);
    const statusType = baseScore >= 75 ? "good" : (baseScore >= 55 ? "caution" : "bad");
    const moonSignName = RASHI_LIST[r.moonSignIndex];
    const festivalLine = r.hasFestival ? `आज ${r.dateEnglish.replace(' 2026', '')} को ${r.festival} है।` : `आज ${r.festival} है।`;
    return {
        dateHindi: r.dateHindi,
        dateEnglish: r.dateEnglish,
        festival: r.festival,
        moonSignIndex: r.moonSignIndex,
        nakshatraIndex: r.nakshatraIndex,
        panchang: Object.assign({}, p, { dishaShool: wMeta.disha }),
        liveWindows: {
            abhijit: { start: r.w.abhijit[0], end: r.w.abhijit[1], label: "अभिजीत मुहूर्त (Best for Important Work)" },
            amrit: { start: r.w.amrit[0], end: r.w.amrit[1], label: "अमृत चौघड़िया (Shubh Spiritual & Business Window)" },
            rahu: { start: r.w.rahu[0], end: r.w.rahu[1], label: "राहु काल (Avoid Starting New Work)" },
            yamaganda: { start: r.w.yama[0], end: r.w.yama[1], label: "यमगंड (Avoid Financial Risk)" }
        },
        activities: {
            vehicle: {
                status: statusType,
                score: `${Math.min(98, baseScore + 4)}%`,
                title: r.caution ? "सावधानी रखें (Check Muhurat)" : "वाहन/गैजेट खरीद हेतु अनुकूल",
                desc: `आज ${nakName} नक्षत्र और ${wMeta.hi} का संयोग है। राहु काल (${p.rahuKaal}) को छोड़कर अमृत चौघड़िया (${p.amritKaal.replace(' (अमृत चौघड़िया)', '')}) या अभिजीत मुहूर्त में खरीदारी करें।`
            },
            finance: {
                status: r.dow === 2 || r.caution ? "caution" : "good",
                score: r.dow === 2 ? "45%" : `${baseScore}%`,
                title: r.dow === 2 ? "मंगलवार को कर्ज लेने से बचें" : "निवेश व धन लेन-देन हेतु शुभ",
                desc: r.dow === 2
                    ? "मंगलवार के दिन नया कर्ज लेना वर्जित माना गया है, किंतु पुराना ऋण चुकाने के लिए यह दिन अच्छा है।"
                    : `आज ${moonSignName} के चंद्रमा में वित्तीय योजनाएं और बैंकिंग कार्य राहु काल (${p.rahuKaal}) छोड़कर करें।`
            },
            travel: {
                status: r.caution ? "caution" : "good",
                score: `${baseScore + 2}%`,
                title: "दिशा शूल का ध्यान रखकर यात्रा करें",
                desc: `आज ${wMeta.disha}। यात्रा से पहले यह उपाय करें और राहु काल (${p.rahuKaal}) में प्रस्थान न करें।`
            },
            property: {
                status: statusType,
                score: `${baseScore}%`,
                title: r.caution ? "केवल कागजी समीक्षा करें" : "प्रॉपर्टी व गृह कार्यों हेतु उत्तम",
                desc: `आज ${r.yogaShort} योग और ${nakName} नक्षत्र के प्रभाव में भूमि/मकान संबंधी चर्चा और वास्तु कार्य किए जा सकते हैं।`
            },
            career: {
                status: "good",
                score: `${Math.min(96, baseScore + 8)}%`,
                title: "करियर, शिक्षा व मीटिंग्स हेतु श्रेष्ठ",
                desc: `${wMeta.hi} (${wMeta.planet}) के प्रभाव से आज कार्यक्षेत्र में वरिष्ठों से संवाद और नए प्रोजेक्ट की रूपरेखा बनाने में सफलता मिलेगी।`
            },
            medical: {
                status: (r.dow === 2 || r.dow === 6 || r.caution) ? "bad" : "good",
                score: (r.dow === 2 || r.dow === 6 || r.caution) ? "35%" : "80%",
                title: (r.dow === 2 || r.dow === 6 || r.caution) ? "आज बाल/नाखून काटना टालें" : "ग्रूमिंग व दिनचर्या हेतु अनुकूल",
                desc: (r.dow === 2 || r.dow === 6 || r.caution)
                    ? "आज की तिथि/वार के अनुसार बाल कटवाना, शेविंग या कॉस्मेटिक काम टालना शास्त्रों में हितकर माना गया है।"
                    : "बाल कटवाने, ग्रूमिंग और नियमित दिनचर्या के लिए आज का दिन अनुकूल है।"
            }
        },
        guidance: [
            { icon: "🕉️", title: r.festival, text: `${festivalLine} आज चंद्रमा ${moonSignName} राशि और ${nakName} नक्षत्र में गोचर कर रहे हैं।` },
            { icon: "🪐", title: `${wMeta.hi} एवं ग्रह प्रभाव`, text: `आज का दिन ${wMeta.planet} द्वारा शासित है। चंद्रमा के ${moonSignName} में होने से कर्म और भावनाओं में संतुलन रखें। उपाय: ${wMeta.remedy}` },
            { icon: "⏳", title: "राहु काल एवं मुहूर्त", text: `आज राहु काल ${p.rahuKaal} है। इस अवधि में नया शुभ कार्य शुरू न करें। श्रेष्ठ समय: अभिजीत ${p.abhijitMuhurat}, अमृत चौघड़िया ${p.amritKaal.replace(' (अमृत चौघड़िया)', '')}।` }
        ]
    };
}

Object.keys(PANCHANG_2026).forEach(k => { ASTRO_DATABASE[k] = buildComputedDay(k, PANCHANG_2026[k]); });

// ============================================================================
// DYNAMIC ASTRONOMICAL FALLBACK ENGINE (For dates after 31 December 2026)
// Prevents the site from crashing or freezing on old dates if database is not updated.
// ============================================================================

function generateDynamicAstroFallback(dateKey) {
    const parts = dateKey.split('-').map(Number);
    const dateObj = new Date(parts[0], parts[1] - 1, parts[2]);
    const dow = dateObj.getDay();
    const wMeta = WEEKDAY_META[dow];

    const refEpoch2000 = Math.floor(new Date(2000, 0, 1).getTime() / 86400000);
    const epochDays = Math.floor(dateObj.getTime() / 86400000);
    const daysSince2000 = epochDays - refEpoch2000;

    // Approximate Lunar Position & Nakshatra (~27.32166 days per revolution)
    const lunarCycles = (daysSince2000 / 27.321661) + 0.52;
    const normPhase = ((lunarCycles % 1) + 1) % 1;
    const moonIdx = Math.floor(normPhase * 12) % 12;
    const nakIdx = Math.floor(normPhase * 27) % 27;

    // Approximate Tithi (~29.530588 days Synodic cycle)
    const synodicCycles = (daysSince2000 / 29.530588) + 0.18;
    const synodicPhase = ((synodicCycles % 1) + 1) % 1;
    const tithiNum = Math.floor(synodicPhase * 30) + 1;
    const paksha = tithiNum <= 15 ? "शुक्ल पक्ष" : "कृष्ण पक्ष";
    const tithiName = tithiNum <= 15 ? `तिथि ${tithiNum}` : `तिथि ${tithiNum - 15}`;

    // Approximate Solar Ingress
    const month = parts[1];
    const day = parts[2];
    const sunIdx = (month + (day >= 15 ? 0 : -1) + 9) % 12;

    const baseScore = 75;
    const nakName = NAKSHATRA_LIST[nakIdx];

    return {
        dateHindi: `${wMeta.hi}, ${day} ${parts[0]}-${parts[1]}`,
        dateEnglish: `${day}/${month}/${parts[0]}`,
        festival: "दैनिक वैदिक गोचर",
        moonSignIndex: moonIdx,
        nakshatraIndex: nakIdx,
        panchang: {
            tithi: `${paksha} (${tithiName})`,
            nakshatra: nakName,
            yoga: "सिद्धि योग",
            karana: "बव / बालव",
            paksha: paksha,
            masa: "सौर मास",
            sunrise: "06:30 AM",
            sunset: "05:25 PM",
            moonrise: "06:15 PM",
            moonset: "06:45 AM",
            moonSign: RASHI_LIST[moonIdx],
            sunSign: RASHI_LIST[sunIdx],
            brahmaMuhurat: "04:45 AM - 05:35 AM",
            abhijitMuhurat: dow === 3 ? "बुधवार को अभिजित वर्जित" : "11:35 AM - 12:20 PM",
            amritKaal: "08:30 AM - 10:10 AM",
            godhuliMuhurat: "05:15 PM - 05:40 PM",
            rahuKaal: wMeta.rahu[2],
            yamaganda: wMeta.yama[2],
            gulikaKaal: wMeta.gulika[2],
            varjyam: "रात्रि 09:10 PM - 10:45 PM",
            dishaShool: wMeta.disha
        },
        liveWindows: {
            abhijit: { start: "11:35", end: "12:20", label: "अभिजीत मुहूर्त" },
            amrit: { start: "08:30", end: "10:10", label: "अमृत काल" },
            rahu: { start: wMeta.rahu[0], end: wMeta.rahu[1], label: "राहु काल" },
            yamaganda: { start: wMeta.yama[0], end: wMeta.yama[1], label: "यमगंड" }
        },
        activities: {
            vehicle: { status: "good", score: "80%", title: "शुभ चौघड़िया में खरीदारी करें", desc: `आज ${nakName} में राहु काल छोड़कर कार्य करें।` },
            finance: { status: "good", score: "78%", title: "वित्तीय लेन-देन हेतु अनुकूल", desc: `अभिजीत या अमृत काल में लेन-देन लाभप्रद रहेगा।` },
            travel: { status: "good", score: "76%", title: "दिशा शूल का ध्यान रखें", desc: `आज ${wMeta.disha}।` },
            property: { status: "good", score: "75%", title: "प्रॉपर्टी कार्य हेतु सामान्य", desc: `कागजी समीक्षा के लिए दिन अनुकूल है।` },
            career: { status: "good", score: "82%", title: "करियर व मीटिंग्स हेतु श्रेष्ठ", desc: `${wMeta.hi} के प्रभाव से कार्यों में गति आएगी।` },
            medical: { status: "good", score: "75%", title: "स्वास्थ्य दिनचर्या बनाए रखें", desc: `नियमित योग व ध्यान करें।` }
        },
        guidance: [
            { icon: "🕉️", title: "दैनिक वैदिक पंचांग", text: `आज चंद्रमा ${RASHI_LIST[moonIdx]} में गोचर कर रहे हैं।` },
            { icon: "🪐", title: `${wMeta.hi} एवं ग्रह प्रभाव`, text: `आज का दिन ${wMeta.planet} द्वारा शासित है। उपाय: ${wMeta.remedy}` },
            { icon: "⏳", title: "मुहूर्त सावधानी", text: `राहु काल (${wMeta.rahu[2]}) में नए कार्यों से बचें।` }
        ]
    };
}

// Proxy wrapper so any date accessed automatically resolves without returning undefined
const ASTRO_DATA_PROXY = new Proxy(ASTRO_DATABASE, {
    get: function(target, prop) {
        if (typeof prop === "string" && /^\d{4}-\d{2}-\d{2}$/.test(prop)) {
            if (!target[prop]) {
                target[prop] = generateDynamicAstroFallback(prop);
            }
            return target[prop];
        }
        return target[prop];
    }
});

// Export database globally
window.ASTRO_DATABASE = ASTRO_DATA_PROXY;
